// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, uint256 withdrawAmount, address attacker) public {
        vm.assume(amount > 0);
        vm.assume(address(c).balance == 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(c.owner());
        c.sendMoney(target, 0);
        vm.prank(attacker);
        vm.deal(attacker, 0);
        try c.withdraw(withdrawAmount) { } catch { }
        assertEq(address(c).balance, balanceBefore);
    }
}
